describe("doctests of sympy.printing.mathml", () => {
  it("print_mathml(x+1) #doctest: +NORMALIZE_WHITESPACE", () => {
    const x = new Sym('x');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(printMathml(add(1, x), {}), true)).toBe('<apply> <plus/> <ci>x</ci> <cn>1</cn> </apply>');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("print_mathml(x+1, printer='presentation')", () => {
    const x = new Sym('x');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(printMathml(add(1, x), { printer: 'presentation' }))).toBe('<mrow>\n\t<mi>x</mi>\n\t<mo>+</mo>\n\t<mn>1</mn>\n</mrow>');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
});

